import test from 'node:test';
import assert from 'node:assert/strict';

import { parseRange } from '../src/parseRange.js';

test('expands an inclusive range', () => {
  assert.deepEqual(parseRange('3-7'), [3, 4, 5, 6, 7]);
});

test('throws on malformed input', () => {
  assert.throws(() => parseRange('abc'), /bad range: abc/);
  assert.throws(() => parseRange('3-'), /bad range: 3-/);
  assert.throws(() => parseRange('3 - 7'), /bad range: 3 - 7/);
});

test('throws on an inverted range', () => {
  assert.throws(() => parseRange('7-3'), /inverted range: 7-3/);
});

test('throws on a range wider than 1000', () => {
  assert.throws(() => parseRange('0-1001'), /range too wide: 0-1001/);
  // The guard is on the span (hi - lo), so a span of exactly 1000 is allowed.
  assert.equal(parseRange('0-1000').length, 1001);
});

